// NewClassicPoliciesCmd creates the classic-policies command group
func NewClassicPoliciesCmd(ctx *registry.CLIContext) *cobra.Command {
	cmd := &cobra.Command{
		Use:         "classic-policies",
		Short:       "Deployment policies (Classic API)",
		Long:        `Manage deployment policies via the Jamf Pro Classic API (/JSSResource/).`,
		Annotations: map[string]string{"jamf:api": "pro-classic"},
	}

	cmd.AddCommand(newClassicPoliciesListCmd(ctx))

	cmd.AddCommand(newClassicPoliciesGetCmd(ctx))

	cmd.AddCommand(newClassicPoliciesCreateCmd(ctx))

	cmd.AddCommand(newClassicPoliciesUpdateCmd(ctx))

	cmd.AddCommand(newClassicPoliciesDeleteCmd(ctx))

	cmd.AddCommand(newClassicPoliciesApplyCmd(ctx))

	cmd.AddCommand(scope.NewScopeCmd(ctx, scope.Resource{
		APIPath:     "policies",
		SingularKey: "policy",
	}))

	return cmd
}

func newClassicPoliciesListCmd(ctx *registry.CLIContext) *cobra.Command {
	return &cobra.Command{
		Use:   "list",
		Short: "List all policies",
		Example: `  # List all policies
  jamf-cli pro classic-policies list

  # List policies and extract IDs
  jamf-cli pro classic-policies list --field id`,
		Annotations: map[string]string{"jamf:api": "pro-classic", "jamf:gateway-privileges": "policies:read"},
		RunE: func(cmd *cobra.Command, args []string) error {
			reqCtx := cmd.Context()
			resp, err := ctx.Client.Do(reqCtx, "GET", "/JSSResource/policies", nil)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			// Classic API returns XML list responses.
			body, err := io.ReadAll(resp.Body)
			if err != nil {
				return err
			}
			// Default to pretty-printed XML; use -o json/yaml/table/csv for structured output.
			// -o xml = pretty-printed XML, -o raw = exact wire bytes.
			if (!cmd.Flags().Changed("output") && !cmd.Flags().Changed("field") && ctx.Output.Format() == "json") || ctx.Output.Format() == "xml" || ctx.Output.Format() == "raw" {
				return ctx.Output.PrintBytes(body)
			}
			if xmlconv.IsXML(body) {
				items, err := xmlconv.ExtractListItems(body)
				if err == nil {
					jsonItems, err := json.Marshal(items)
					if err == nil {
						return ctx.Output.PrintRaw(jsonItems)
					}
				}
				return ctx.Output.PrintRaw(body)
			}
			// JSON fallback
			var wrapper map[string]json.RawMessage
			if err := json.Unmarshal(body, &wrapper); err == nil {
				if inner, ok := wrapper["policies"]; ok {
					return ctx.Output.PrintRaw(inner)
				}
			}
			return ctx.Output.PrintRaw(body)
		},
	}
}

func newClassicPoliciesGetCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		flagName string
	)

	cmd := &cobra.Command{
		Use:   "get [<id>]",
		Short: "Get a policy by ID",
		Example: `  # Get a policy by ID
  jamf-cli pro classic-policies get 1

  # Get a policy by name
  jamf-cli pro classic-policies get --name "Example"

  # Get a policy and output as YAML
  jamf-cli pro classic-policies get 1 -o yaml`,
		Annotations: map[string]string{"jamf:api": "pro-classic", "jamf:gateway-privileges": "policies:read"},
		Args:        cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			reqCtx := cmd.Context()

			// Resolve lookup: check flags first, then positional ID
			var path string
			if flagName != "" {
				path = fmt.Sprintf("/JSSResource/policies/name/%s", registry.EscapeClassicPathSegment(flagName))
			} else if len(args) > 0 {
				path = fmt.Sprintf("/JSSResource/policies/id/%s", url.PathEscape(args[0]))
			} else {
				return fmt.Errorf("provide an <id> argument, --name")
			}

			resp, err := ctx.Client.Do(reqCtx, "GET", path, nil)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			// Classic API returns XML; pass through by default.
			body, err := io.ReadAll(resp.Body)
			if err != nil {
				return err
			}
			// Default to pretty-printed XML; use -o json/yaml/table/csv for structured output.
			// -o xml = pretty-printed XML, -o raw = exact wire bytes.
			if (!cmd.Flags().Changed("output") && !cmd.Flags().Changed("field") && ctx.Output.Format() == "json") || ctx.Output.Format() == "xml" || ctx.Output.Format() == "raw" {
				return ctx.Output.PrintBytes(body)
			}
			if xmlconv.IsXML(body) {
				if jsonBody, err := xmlconv.ToJSON(body); err == nil {
					body = jsonBody
				}
			}
			var wrapper map[string]json.RawMessage
			if err := json.Unmarshal(body, &wrapper); err == nil {
				if inner, ok := wrapper["policy"]; ok {
					return ctx.Output.PrintRaw(inner)
				}
			}
			return ctx.Output.PrintRaw(body)
		},
	}

	cmd.Flags().StringVar(&flagName, "name", "", "Look up policy by name")

	return cmd
}

